CREATE TABLE IF NOT EXISTS app_menu (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_id INTEGER REFERENCES app_menu(id) ON DELETE SET NULL, name TEXT NOT NULL, description TEXT, url TEXT, sort INTEGER NOT NULL, "group" TEXT NOT NULL DEFAULT 'main', icon TEXT, active INTEGER NOT NULL DEFAULT 1, display INTEGER NOT NULL DEFAULT 1, created_by TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_by TEXT, updated_at DATETIME);
